"""Write the two-moons data for the `bagging-trees` lab as a small JSON file. No download: `make_moons` is generated by
scikit-learn (https://scikit-learn.org/stable/modules/generated/sklearn.datasets.make_moons.html).

    .venv/bin/python scripts/figures/playground_moons.py

Writes only src/lib/playground/labs/data/moons.json.

Why DATA_SEED = 2: the lab's story is "averaging many unstable trees beats one tree". To avoid showing a lucky data set, the
seed was chosen by a rule fixed before looking at the lab: over the data seeds 0..29 (training set make_moons(300, noise=0.3,
random_state=s), test set make_moons(1000, noise=0.3, random_state=s + 1000), 4 decimals), take the seed whose gain of 50 bagged
fully grown trees over one fully grown tree is closest to the mean gain over the 30 seeds. That seed is 2 (see
`pick_seed()` below, which reproduces the choice; the bootstrap seed is the lab's BOOTSTRAP_SEED).
"""
import json
from pathlib import Path

import numpy as np
from sklearn.datasets import make_moons
from sklearn.tree import DecisionTreeClassifier

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "src/lib/playground/labs/data/moons.json"
DATA_SEED = 2
TEST_SEED = DATA_SEED + 1000
N_TRAIN, N_TEST, NOISE = 300, 1000, 0.3
BOOTSTRAP_SEED = 20260618  # same value as BOOTSTRAP_SEED in src/lib/playground/labs/trees.ts


def mulberry32(seed):
    """NumPy-free port of src/lib/imagekit/rng.ts mulberry32 (32-bit arithmetic)."""
    m = 0xFFFFFFFF
    state = [seed & m]

    def nxt():
        state[0] = (state[0] + 0x6D2B79F5) & m
        t = state[0]
        t = ((t ^ (t >> 15)) * (t | 1)) & m
        t ^= (t + (((t ^ (t >> 7)) * (t | 61)) & m)) & m
        return ((t ^ (t >> 14)) & m) / 4294967296

    return nxt


def make(seed, n):
    x, y = make_moons(n, noise=NOISE, random_state=seed)
    return np.round(x, 4), y


def pick_seed(seeds=range(30), m=50):
    gains = []
    for s in seeds:
        x, y = make(s, N_TRAIN)
        xt, yt = make(s + 1000, N_TEST)
        rng = mulberry32(BOOTSTRAP_SEED)
        votes = np.zeros(N_TEST)
        for _ in range(m):
            idx = np.array([int(rng() * N_TRAIN) for _ in range(N_TRAIN)])
            votes += DecisionTreeClassifier(random_state=0).fit(x[idx], y[idx]).predict(xt)
        bag = np.mean(np.where(votes * 2 == m, 0.5, (votes * 2 > m) != yt))
        single = np.mean(DecisionTreeClassifier(random_state=0).fit(x, y).predict(xt) != yt)
        gains.append(single - bag)
    gains = np.array(gains)
    return list(seeds)[int(np.argmin(np.abs(gains - gains.mean())))], gains


def main() -> None:
    x, y = make(DATA_SEED, N_TRAIN)
    xt, yt = make(TEST_SEED, N_TEST)
    payload = {
        "source": "scikit-learn sklearn.datasets.make_moons (generated, no download)",
        "noise": NOISE,
        "dataSeed": DATA_SEED,
        "testSeed": TEST_SEED,
        "bootstrapSeed": BOOTSTRAP_SEED,
        "train": {"x": x.tolist(), "y": [int(v) for v in y]},
        "test": {"x": xt.tolist(), "y": [int(v) for v in yt]},
    }
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(json.dumps(payload, separators=(",", ":")) + "\n")
    print(f"wrote {OUT} ({OUT.stat().st_size} bytes; {len(y)} train, {len(yt)} test)")


if __name__ == "__main__":
    main()
